def my_map(fn, items):
    return [fn(item) for item in items]


def my_filter(fn, items):
    return [item for item in items if fn(item)]


def compose(*fns):
    def composed(x):
        result = x
        for fn in reversed(fns):
            result = fn(result)
        return result
    return composed


def pipe(*fns):
    def piped(x):
        result = x
        for fn in fns:
            result = fn(result)
        return result
    return piped
